def top_run(b, c):
    h = b.heights[c]
    if h == 0 or h >= 6:
        return 0
    n = 0
    r = h - 1
    while r >= 0 and b.grid[r][c] == 2:
        n += 1
        r -= 1
    return n

def early(b):
    # opening: opponent has a bottom stone in col 3 or 5, I have no stone in cols 2-4
    if b.ply < 2 or b.ply > 6:
        return False
    if any(b.grid[r][c] == 1 for c in (2, 3, 4) for r in range(2)):
        return False
    return b.grid[0][3] == 2 or b.grid[0][5] == 2

def fires(b):
    if early(b):
        return True
    if b.heights[1] > 1:
        return False
    return any(top_run(b, c) >= 2 for c in range(2, 7))

def level(b):
    if not fires(b):
        return 0
    best = max(top_run(b, c) for c in range(7))
    if early(b):
        return 7
    return min(9, 3 + 2 * best)

def raw(b):
    s = 0.0
    if b.heights[1] == 0:
        s += 2.0
    elif b.heights[1] == 1:
        s += 0.5
    if b.heights[0] <= 2:
        s += 0.5
    if b.me_first:
        s += 1.0
    # opponent stones low on the centre/right
    for (r, c) in ((0, 3), (0, 5), (1, 5), (0, 6), (1, 6), (1, 3)):
        if b.grid[r][c] == 2:
            s += 0.7
    # opponent stones in column 1 or my stones stacked in the centre hurt
    for r in range(6):
        if b.grid[r][1] == 2:
            s -= 1.0
    s -= b.ply / 12.0
    return s

def fires(b):
    return b.ply >= 2 and raw(b) >= 3.0

def level(b):
    if b.ply < 2:
        return 0
    v = int(round((raw(b) - 1.5) * 2))
    return max(0, min(9, v))
